/*
 * PWA e push no navegador (backend em extend/push.php):
 *
 * - registra o /canela-sw depois do load, sem pesar na primeira pintura;
 * - a coluna "Push" na tabela de notificações (o canal do servidor);
 * - em Configurações → Notificações, o botão que liga ou desliga o push
 *   neste aparelho (pede a permissão do navegador e grava o aparelho).
 */
import app from 'flarum/forum/app';
import { extend } from 'flarum/common/extend';
import Component from 'flarum/common/Component';
import Button from 'flarum/common/components/Button';
import { forumBool, t } from '../../utils/settings';
const supported = () => 'serviceWorker' in navigator && 'PushManager' in window && 'Notification' in window;
const pushKey = () => app.forum.attribute('canelaPushKey') || null;
const base = () => String(app.forum.attribute('baseUrl') || '').replace(/\/$/, '');
function registration() {
  return navigator.serviceWorker.register(`${base()}/canela-sw`, {
    scope: `${base()}/`
  });
}

/** A chave VAPID (base64url) no formato que o PushManager pede. */
function keyBytes(key) {
  const raw = atob((key + '='.repeat((4 - key.length % 4) % 4)).replace(/-/g, '+').replace(/_/g, '/'));
  return Uint8Array.from(raw, char => char.charCodeAt(0));
}
function send(method, body) {
  return app.request({
    method,
    url: `${app.forum.attribute('apiUrl')}/canela-push-subscriptions`,
    body
  });
}
class PushToggle extends Component {
  status = 'loading';
  busy = false;
  oninit(vnode) {
    super.oninit(vnode);
    if (!supported()) {
      this.status = 'unsupported';
      return;
    }
    registration().then(reg => reg.pushManager.getSubscription()).then(sub => {
      this.status = Notification.permission === 'denied' ? 'denied' : sub ? 'on' : 'off';
      m.redraw();
    }).catch(() => {
      // O navegador aceita push, mas o service worker não carregou.
      this.status = 'error';
      m.redraw();
    });
  }
  view() {
    const on = this.status === 'on';
    return m("div", {
      className: "CanelaPush"
    }, m("div", {
      className: "CanelaPush-text"
    }, m("strong", null, t('push.title')), m("span", {
      className: "helpText"
    }, t(`push.state_${this.status}`))), this.status === 'on' || this.status === 'off' ? m(Button, {
      className: on ? 'Button' : 'Button Button--primary',
      icon: on ? 'far fa-bell-slash' : 'far fa-bell',
      loading: this.busy,
      onclick: () => this.toggle()
    }, on ? t('push.disable') : t('push.enable')) : null);
  }
  async toggle() {
    this.busy = true;
    m.redraw();
    try {
      const reg = await registration();
      const current = await reg.pushManager.getSubscription();
      if (current) {
        await send('DELETE', {
          endpoint: current.endpoint
        });
        await current.unsubscribe();
        this.status = 'off';
      } else if ((await Notification.requestPermission()) !== 'granted') {
        this.status = 'denied';
      } else {
        const sub = await reg.pushManager.subscribe({
          userVisibleOnly: true,
          applicationServerKey: keyBytes(pushKey())
        });
        await send('POST', sub.toJSON());
        this.status = 'on';
      }
    } catch {
      app.alerts.show({
        type: 'error'
      }, t('push.error'));
    }
    this.busy = false;
    m.redraw();
  }
}
export default function installPush() {
  // Depois do load: o service worker não disputa banda com o fórum.
  const register = () => {
    if ('serviceWorker' in navigator && (forumBool('canelaPwa', true) || pushKey())) registration().catch(() => {});
  };
  if (document.readyState === 'complete') app.beforeMount(register);else window.addEventListener('load', register, {
    once: true
  });
  extend('flarum/forum/components/NotificationGrid', 'notificationMethods', function (items) {
    if (pushKey()) items.add('push', {
      name: 'push',
      icon: 'fas fa-mobile-screen',
      label: t('push.column')
    });
  });

  // Pelo nome do módulo: a página de configurações é um pedaço sob demanda.
  extend('flarum/forum/components/SettingsPage', 'notificationsItems', function (items) {
    if (pushKey()) items.add('canelaPush', m(PushToggle, null), 110);
  });
}
flarum.reg.add('ramon-canela', 'forum/features/push', installPush);